using System.Numerics;
using OpenScct.Animation;
using OpenScct.Content;
using OpenScct.Editor.Core.Animation;

string root = Path.Combine(Path.GetTempPath(), "OpenSCCT-AnimationChecks", Guid.NewGuid().ToString("N"));
Directory.CreateDirectory(root);
int checks = 0;
void Check(bool value, string name) { checks++; if (!value) throw new Exception(name); Console.WriteLine("PASS " + name); }
void Near(float value, float expected, string name, float tolerance = .0001f) => Check(MathF.Abs(value - expected) < tolerance, name + $" ({value:0.####})");
void Reject(Action action, string name) { bool rejected = false; try { action(); } catch (Exception e) when (e is InvalidDataException or ArgumentException or IOException) { rejected = true; } Check(rejected, name); }
var skeleton = new SkeletonDefinition { Name = "Synthetic", Bones = [new() { Name = "Root" }, new() { Name = "Elbow", Parent = 0, Rest = new(Vector3.UnitX, Quaternion.Identity, Vector3.One) }, new() { Name = "Hand", Parent = 1, Rest = new(Vector3.UnitX, Quaternion.Identity, Vector3.One) }] };
var clip = new AnimationClip { Name = "Move", Skeleton = skeleton.Id, Duration = 1, Tracks = [new() { Bone = "Root", Channel = TrackChannel.Translation, Keys = [new() { Time = 0 }, new() { Time = 1, Value = new(2, 0, 0, 0) }] }] };
var project = new AnimationProject { Skeletons = [skeleton], Clips = [clip], Scene = [new() { Skeleton = skeleton.Id, Clip = clip.Id }] };
Near(ClipEvaluator.Evaluate(skeleton, clip, .5f)[0].Position.X, 1, "linear midpoint");
clip.Tracks[0].Keys[0].Interpolation = KeyInterpolation.Step;
Near(ClipEvaluator.Evaluate(skeleton, clip, .5f)[0].Position.X, 0, "step midpoint");
clip.Tracks[0].Keys[0].Interpolation = KeyInterpolation.Cubic; clip.Tracks[0].Keys[0].OutTangent = new(4, 0, 0, 0);
Near(ClipEvaluator.Evaluate(skeleton, clip, .5f)[0].Position.X, 1.5f, "cubic tangent midpoint");
byte[] document = AnimationJson.Write(project); var restored = AnimationJson.Read(document);
Check(document.AsSpan().SequenceEqual(AnimationJson.Write(restored)), "lossless project roundtrip");
var session = new AnimationSession(project);
session.Edit("rename", p => p.Clips[0].Name = "Renamed"); Check(session.Dirty && session.CanUndo, "history dirty tracking");
session.Undo(); Check(session.Project.Clips[0].Name == "Move" && !session.Dirty, "undo checkpoint");
session.Redo(); Check(session.Project.Clips[0].Name == "Renamed", "redo");
session.Save(Path.Combine(root, "test.osanim")); Check(!session.Dirty, "save checkpoint");
session.Edit("key", p => p.Clips[0].Tracks[0].Keys[0].OutTangent = new(6, 0, 0, 0)); session.Save();
Check(File.Exists(Path.Combine(session.Folder!, "animation.json.previous")), "journal previous document");
Check(AnimationSession.Open(session.Folder!).Project.Clips[0].Tracks[0].Keys[0].OutTangent.X == 6, "saved tangents");
session.Autosave(Path.Combine(root, "recovery")); Check(File.Exists(Path.Combine(root, "recovery", project.Id + ".json")), "recovery document");
Reject(() => session.Edit("invalid", p => p.Clips[0].Tracks[0].Keys.Add(new() { Time = 0 })), "invalid transaction rejected");
Check(session.Project.Clips[0].Tracks[0].Keys.Count == 2, "failed edit rolled back");
byte[] glb = AnimationExport.Glb(project, skeleton.Id); string glbPath = Path.Combine(root, "sample.glb"); File.WriteAllBytes(glbPath, glb);
var imported = AnimationImport.Read(glbPath); Near(ClipEvaluator.Evaluate(imported.Skeletons[0], imported.Clips[0], .5f)[0].Position.X, 1.5f, "glTF cubic keys preserved");
AnimationExport.Write(project, skeleton.Id, Path.Combine(root, "sample.gltf")); Check(AnimationImport.Read(Path.Combine(root, "sample.gltf")).Clips.Count == 1, "external glTF buffer export/import");
var baked = AnimationEdits.Bake(skeleton, clip); Near(ClipEvaluator.Evaluate(skeleton, baked, .5f)[0].Position.X, 1.5f, "baked curve midpoint");
var trimmed = AnimationJson.Clone(clip); AnimationEdits.Trim(trimmed, .25f, .75f); Near(trimmed.Duration, .5f, "trim duration");
var reversed = AnimationJson.Clone(clip); AnimationEdits.Reverse(reversed); Near(ClipEvaluator.Evaluate(skeleton, reversed, .5f)[0].Position.X, 1.5f, "reversed tangents");
AnimationEdits.Retime(reversed, 2); Near(ClipEvaluator.Evaluate(skeleton, reversed, 1)[0].Position.X, 1.5f, "retime tangent scale");
var layered = AnimationJson.Clone(clip); layered.Layers.Add(new() { Weight = .5f, Additive = true, Mask = ["Root"], Tracks = [new() { Bone = "Root", Channel = TrackChannel.Translation, Keys = [new() { Time = 0, Value = new(0, 2, 0, 0) }] }] });
Near(ClipEvaluator.Evaluate(skeleton, layered, .5f)[0].Position.Y, 1, "masked additive layer");
var ik = skeleton.Bones.Select(b => b.Rest).ToArray(); RigSolver.Apply(skeleton, ik, [new() { Bone = "Hand", Kind = ConstraintKind.TwoBoneIk, Target = new(1, 1, 0), Pole = Vector3.UnitY }], 0);
Check(Vector3.Distance(ClipEvaluator.World(skeleton, ik)[2].Translation, new(1, 1, 0)) < .001f, "two-bone IK target");
var chain = skeleton.Bones.Select(b => b.Rest).ToArray(); RigSolver.Apply(skeleton, chain, [new() { Bone = "Hand", Root = "Root", Kind = ConstraintKind.ChainIk, Target = new(1, 1, 0) }], 0);
Check(Vector3.Distance(ClipEvaluator.World(skeleton, chain)[2].Translation, new(1, 1, 0)) < .01f, "chain IK target");
var targetSkeleton = AnimationJson.Clone(skeleton); targetSkeleton.Id = Guid.NewGuid().ToString("N"); project.Skeletons.Add(targetSkeleton);
var profile = new RetargetProfile { SourceSkeleton = skeleton.Id, TargetSkeleton = targetSkeleton.Id, RootScale = 2, Bones = skeleton.Bones.ToDictionary(b => b.Name, b => b.Name) };
var retargeted = AnimationEdits.Retarget(project, clip, profile); Near(ClipEvaluator.Evaluate(targetSkeleton, retargeted, .5f)[0].Position.X, 3, "retarget root scale/rest correction");
clip.Events = [new() { Time = 0, Target = "start" }, new() { Time = .5f, Target = "middle" }]; clip.Loop = true;
Check(ClipEvaluator.Events(clip, 0, .5f, true).Count() == 2, "start and forward event edges");
Check(!ClipEvaluator.Events(clip, .5f, .5f).Any(), "seeking has no repeated event");
Check(ClipEvaluator.Events(clip, .75f, 1.5f).Count() == 2, "loop crossing event edges");
var node = new GraphNode { Clip = clip.Id };
var graph = new AnimationGraph { Skeleton = skeleton.Id, Nodes = [node], States = [new() { Name = "Idle", Node = node.Id }, new() { Name = "Move", Node = node.Id }], Parameters = [new() { Name = "Go", Kind = ParameterKind.Trigger }], Transitions = [new() { From = "Idle", To = "Move", Parameter = "Go", Operator = ConditionOperator.Triggered, BlendSeconds = .2f }] };
project.Graphs.Add(graph); AnimationJson.Validate(project); var player = new GraphPlayer(project, graph); player.Set("Go", 1); player.Advance(.1f);
Check(player.State == "Move" && player.Capture().Parameters["Go"] == 0, "graph trigger transition consumption");
var mirror = new GraphPlayer(project, graph); mirror.Restore(player.Capture()); Near(mirror.Evaluate()[0].Position.X, player.Evaluate()[0].Position.X, "graph late-join pose");
node.Inputs.Add(new() { Node = node.Id }); Reject(() => AnimationJson.Validate(project), "graph cycles rejected"); node.Inputs.Clear();
var sequence = new AnimationSequence { Duration = 2, Tracks = [new() { Kind = SequenceTrackKind.Event, Events = [new() { Time = 0, Target = "zero" }, new() { Time = 1, Target = "one" }] }] };
var seq = new SequencePlayer(project, sequence); seq.Start(); Check(seq.Advance(.5f).Count == 1, "sequence start event");
var seqLate = new SequencePlayer(project, sequence); seqLate.Restore(seq.Capture()); Check(seqLate.Advance(.5f).Single().Target == "one", "sequence late join does not replay start");
string bvhPath = Path.Combine(root, "sample.bvh");
File.WriteAllText(bvhPath, "HIERARCHY ROOT Hip { OFFSET 0 0 0 CHANNELS 6 Xposition Yposition Zposition Zrotation Xrotation Yrotation JOINT Hand { OFFSET 0 100 0 CHANNELS 3 Zrotation Xrotation Yrotation End Site { OFFSET 0 10 0 } } } MOTION Frames: 2 Frame Time: 0.033333333 0 0 0 0 0 0 0 0 0 100 0 0 0 0 0 0 0 0");
var bvh = AnimationImport.Read(bvhPath); Near(ClipEvaluator.Evaluate(bvh.Skeletons[0], bvh.Clips[0], bvh.Clips[0].Duration)[0].Position.X, 1, "BVH unit conversion");
var psk = AnimationImport.Read(SyntheticFixtures.ActorX(root, false));
Check(psk.Skeletons[0].Model is { } pskModel && new GltfAnimationImport(pskModel).Json["meshes"]!.AsArray().Count == 1, "ActorX PSK skinned mesh conversion");
var psa = AnimationImport.Read(SyntheticFixtures.ActorX(root, true));
Near(ClipEvaluator.Evaluate(psa.Skeletons[0], psa.Clips[0], psa.Clips[0].Duration)[0].Position.X, 1, "ActorX PSA animation keys");
string fbx = SyntheticFixtures.Fbx(root);
if (args.Length >= 2)
{
    AnimationImport.ConvertFbx = path => AnimationFbxProcess.Convert(args[0], args[1], path);
    var converted = AnimationImport.Read(fbx); Check(converted.Clips.Count > 0 && converted.Skeletons[0].Bones.Count > 0, "FBX packaged helper import");
}
Near(ClipEvaluator.Evaluate(skeleton, trimmed, .125f)[0].Position.X, ClipEvaluator.Evaluate(skeleton, clip, .375f)[0].Position.X, "trim preserves cubic shape");
var preservingLayer = AnimationJson.Clone(clip); preservingLayer.Layers.Add(new() { Tracks = [new() { Bone = "Root", Channel = TrackChannel.Rotation, Keys = [new() { Time = 0, Value = new(0, 0, 0, 1) }] }] });
Near(ClipEvaluator.Evaluate(skeleton, preservingLayer, .5f)[0].Position.X, 1.5f, "rotation-only override preserves translation");
project.Bindings.Add(new() { Target = "Test.Mesh", Slot = "Move", Clip = clip.Id });
string pack = Path.Combine(root, "sample.osanimpack"); AnimationPackBuild.Export(project, null, pack);
string installed = AnimationPackBuild.Install(pack, Path.Combine(root, "pack")); Check(AnimationBundle.Load(installed)!.Project.Bindings.Count == 1, "compiled pack roundtrip");
string asset = Path.Combine(installed, "render", "animations", skeleton.Id + ".glb"); File.AppendAllText(asset, "changed"); Reject(() => AnimationBundle.Load(installed), "animation asset digest mismatch rejected");
Reject(() => AnimationBundle.AssetPath(root, "../escape.glb"), "pack path traversal rejected");
var fpProject = AnimationJson.Clone(project);
var armInstance = new RigInstance { Skeleton = skeleton.Id, Clip = clip.Id }; fpProject.Scene.Add(armInstance);
var fp = new FirstPersonProfile { Role = FirstPersonRole.Spy, MainRig = fpProject.Scene[0].Id, ArmsRig = armInstance.Id, Actions = [new() { Name = "Draw", Slot = "DrawP190", Clip = clip.Id, ArmsClip = clip.Id }] };
fpProject.FirstPersonProfiles.Add(fp);
var merc = AnimationJson.Clone(fp); merc.Id = Guid.NewGuid().ToString("N"); merc.Role = FirstPersonRole.Merc; merc.Actions[0].Slot = "FirstDrawStEd2"; fpProject.FirstPersonProfiles.Add(merc);
var fpRoundtrip = AnimationJson.Read(AnimationJson.Write(fpProject));
Check(fpRoundtrip.FirstPersonProfiles.Count == 2 && fpRoundtrip.FirstPersonProfiles[0].ArmsRig == armInstance.Id, "Spy and Merc first-person project roundtrip");
Near(FirstPersonEvaluation.Evaluate(fpProject, fp, "DrawP190", .5f, true)!.Bones[0].Position.X, 1.5f, "first-person arm action pose");
Near(FirstPersonEvaluation.Evaluate(fpProject, merc, "FirstDrawStEd2", .5f, false)!.Bones[0].Position.X, 1.5f, "first-person Merc action pose");
var paired = AnimationJson.Clone(project); paired.Graphs.Clear(); paired.Bindings.Clear();
var partner = new RigInstance { Skeleton = skeleton.Id, Transform = new(new(0, 1, 0), Quaternion.Identity, Vector3.One) }; paired.Scene.Add(partner);
paired.Clips[0].Constraints.Add(new() { Kind = ConstraintKind.Pin, Bone = "Hand", TargetRig = partner.Id, TargetBone = "Hand" });
BoneTransform[] pairedPose = RigSolver.Scene(paired, .5f)[paired.Scene[0].Id];
AnimationClip pairedBake = AnimationEdits.BakeScene(paired, paired.Clips[0]);
Check(Vector3.Distance(ClipEvaluator.World(skeleton, pairedPose)[2].Translation, ClipEvaluator.World(skeleton, ClipEvaluator.Evaluate(skeleton, pairedBake, .5f))[2].Translation) < .001f, "cross-rig pin survives synchronized bake");
var sequenceClip = new AnimationClip { Skeleton = skeleton.Id, Loop = true, Duration = 1, Events = [new() { Time = .25f, Value = "early" }, new() { Time = .75f, Value = "late" }] };
var repeated = new SequencePlayer(new() { Clips = [sequenceClip] }, new() { Duration = 3, Tracks = [new() { Kind = SequenceTrackKind.Skeletal, Segments = [new() { Clip = sequenceClip.Id, Duration = 3 }] }] });
repeated.Start(); Check(string.Join(',', repeated.Advance(2).Select(e => e.Value)) == "early,late,early,late", "looped clip events retain chronological sequence order");
var mapProject = new OpenScct.Editor.Core.Model.MapProject(); var mapAnimation = AnimationJson.Clone(project);
var placement = AnimationMapPlacement.Prepare(mapProject, mapAnimation, clip.Id, new(100, 200, 0)); placement.Do(mapProject);
Check(mapProject.Actors.Count == 1 && mapAnimation.Bindings.Any(b => b.Target == "actor:" + mapProject.Actors[0].Id), "custom animated prop placement binding");
placement.Undo(mapProject); Check(mapProject.Actors.Count == 0, "map prop placement undo"); placement.Do(mapProject);
string mapFolder = Path.Combine(root, "animation.osmap");
new AnimationSession(mapAnimation).Save(Path.Combine(mapFolder, "assets", "animations", mapAnimation.Id + ".osanim"));
OpenScct.Editor.Core.Services.EditorServices.Discover();
var mapBuild = new OpenScct.Editor.Core.Compile.MapCompiler().Compile(mapProject, Path.Combine(root, "built-map"), new() { ProjectFolder = mapFolder, FastLighting = true });
Check(mapBuild.Ok && AnimationBundle.Load(mapBuild.OutputFolder)!.Project.Bindings.Count == 2, "map animation manifest compile/load: " + string.Join("; ", mapBuild.Findings.Where(f => f.Severity == OpenScct.Editor.Core.Services.Severity.Error).Select(f => f.Message)));
var conflicting = AnimationJson.Clone(project); conflicting.Bindings.Add(new() { Target = "test.mesh", Slot = "move", Clip = clip.Id });
Reject(() => AnimationJson.Validate(conflicting), "case-insensitive binding conflict rejected");
string wave = Path.Combine(root, "sample.wav"); File.WriteAllBytes(wave, new byte[44]);
var audioProject = AnimationJson.Clone(project); audioProject.Sequences.Add(new() { Tracks = [new() { Kind = SequenceTrackKind.Audio, Segments = [new() { Asset = wave }] }] });
var audioFiles = AnimationPackBuild.Build(audioProject, null); Check(audioFiles.Keys.Any(p => p.StartsWith("audio/animations/", StringComparison.Ordinal)), "sequence audio copied into content overlay");
var audioSession = new AnimationSession(audioProject); audioSession.Save(Path.Combine(root, "audio.osanim")); audioSession.Autosave(Path.Combine(root, "audio-recovery"));
var recoveredAudio = AnimationSession.Recover(Path.Combine(root, "audio-recovery", audioProject.Id + ".json"));
Check(File.Exists(recoveredAudio.Project.Sequences[^1].Tracks[0].Segments[0].Asset), "audio dependencies survive save and recovery");
AnimationPackBuild.Write(fpProject, null, Path.Combine(root, "preview"));
if (args.Length >= 3)
{
    string stockPath = Path.Combine(args[2], "shared", "chars", "SPerso", "ATT_01.glb");
    var watch = System.Diagnostics.Stopwatch.StartNew(); var stock = AnimationImport.Read(stockPath);
    RigInstance spy = stock.Scene[0]; stock.Scene.Add(new() { Skeleton = spy.Skeleton, Clip = spy.Clip });
    for (int frame = 0; frame < 240; frame++) _ = RigSolver.Scene(stock, frame / 60f);
    Check(stock.Clips.Count > 100, $"two stock rigs, 240 scrub samples ({watch.Elapsed.TotalSeconds:0.00}s including import)");
    Examples.Write(Path.Combine(root, "examples"), args[2]); Check(Directory.GetDirectories(Path.Combine(root, "examples"), "*.osanim").Length == 5, "end-to-end editable examples and runtime overlays");
}
Console.WriteLine($"{checks} animation checks passed. Artifacts: {root}");
